def K(oa, n, F, use, explain, vocab, worked, mistakes, T, ctx, sc, op, rf, ex_, ev=None, prior=None):
    stmt, example, crit, err = op
    notes_ev, notes_fb = NOTES[(oa, n)]
    build(oa, n, F, use=use, prior=prior or PRIOR, explain=explain, vocab=vocab, worked=worked, mistakes=mistakes, T=T, ctx=ctx, sc=sc,
          op=(stmt, example, crit, ev or notes_ev, err, notes_fb),
          reinforce=rf, extend=ex_)


